#include <bits/stdc++.h>
using namespace std;

int n;
vector<long long> req, cap;

// Greedy check: match the leftmost remaining request with the leftmost remaining capacity within distance d.
bool ok(int d) {
    vector<long long> a = req, b = cap;
    int i = 0, j = 0;
    while (i < n && j < n) {
        while (i < n && a[i] == 0) i++;
        while (j < n && b[j] == 0) j++;
        if (i == n || j == n) break;
        if (j < i && i - j > d) { j++; continue; }  // this capacity is too far left for every remaining request
        if (i < j && j - i > d) return false;     // this request cannot reach any remaining capacity
        long long x = min(a[i], b[j]);
        a[i] -= x, b[j] -= x;
    }
    for (long long x : a)
        if (x) return false;
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n;
    req.resize(n), cap.resize(n);
    long long sr = 0, sc = 0;
    for (auto &x : req) cin >> x, sr += x;
    for (auto &x : cap) cin >> x, x--, sc += x;  // the final load must be strictly below max_req
    if (sr > sc) {
        cout << -1 << "\n";
        return 0;
    }
    int lo = 0, hi = n - 1;
    while (lo < hi) {
        int mid = (lo + hi) / 2;
        if (ok(mid)) hi = mid;
        else lo = mid + 1;
    }
    cout << (ok(lo) ? lo : -1) << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    static int n;
    static long[] req, cap;

    static boolean ok(int d) {
        long[] a = req.clone(), b = cap.clone();
        int i = 0, j = 0;
        while (i < n && j < n) {
            while (i < n && a[i] == 0) i++;
            while (j < n && b[j] == 0) j++;
            if (i == n || j == n) break;
            if (j < i && i - j > d) {
                j++;
                continue;
            }
            if (i < j && j - i > d) return false;
            long x = Math.min(a[i], b[j]);
            a[i] -= x;
            b[j] -= x;
        }
        for (long x : a)
            if (x != 0) return false;
        return true;
    }

    public static void main(String[] args) throws IOException {
        n = nextInt();
        req = new long[n];
        cap = new long[n];
        long sr = 0, sc = 0;
        for (int i = 0; i < n; i++) sr += req[i] = nextLong();
        for (int i = 0; i < n; i++) sc += cap[i] = nextLong() - 1;
        if (sr > sc) {
            System.out.println(-1);
            return;
        }
        int lo = 0, hi = n - 1;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (ok(mid)) hi = mid;
            else lo = mid + 1;
        }
        System.out.println(ok(lo) ? lo : -1);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

var n int
var req, capa []int

// ok greedily matches the leftmost remaining request with the leftmost remaining capacity within distance d.
func ok(d int) bool {
	a := slices.Clone(req)
	b := slices.Clone(capa)
	i, j := 0, 0
	for i < n && j < n {
		for i < n && a[i] == 0 {
			i++
		}
		for j < n && b[j] == 0 {
			j++
		}
		if i == n || j == n {
			break
		}
		if j < i && i-j > d {
			j++
			continue
		}
		if i < j && j-i > d {
			return false
		}
		x := min(a[i], b[j])
		a[i] -= x
		b[j] -= x
	}
	for _, x := range a {
		if x != 0 {
			return false
		}
	}
	return true
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n = nextInt()
	req, capa = make([]int, n), make([]int, n)
	sr, sc := 0, 0
	for i := range req {
		req[i] = nextInt()
		sr += req[i]
	}
	for i := range capa {
		capa[i] = nextInt() - 1
		sc += capa[i]
	}
	if sr > sc {
		fmt.Println(-1)
		return
	}
	lo, hi := 0, n-1
	for lo < hi {
		mid := (lo + hi) / 2
		if ok(mid) {
			hi = mid
		} else {
			lo = mid + 1
		}
	}
	if ok(lo) {
		fmt.Println(lo)
	} else {
		fmt.Println(-1)
	}
}
